let dedupState={subId:'quality-dup-card'};
/* 报卡查重：已判定的登记编号 -> 判定类型（'dup'=重卡 | 'multi'=多原发 | 'indep'=独立卡）。
   标记后卡片从「待处理」列表移除；一组若已无「疑似重复」剩余，则该组整组不再显示。
   必须声明在模块级，否则每次重渲染都会丢失标记结果。 */
let dedupMarkedRegs={};
/* 列表视图：''=待处理 | 'dup'=重卡 | 'multi'=多原发 | 'indep'=独立卡 */
let dedupViewState='';
/* 日期筛选：日期类型 + 起止日期（空字符串=不限） */
let dedupDateType='确诊日期';
let dedupDateStart='';
let dedupDateEnd='';
/* 报卡查重「查看」跳转上报数据：按身份证号匹配源数据（sourceDataRecords），
   命中多条时取第一条。找不到则提示，不跳转。 */
function dedupViewSource(registr,pindno){
 if(typeof sourceDataRecords==='undefined'){toast('上报数据模块未加载','error');return}
 const hit=sourceDataRecords.filter(r=>r.idNo&&r.idNo===pindno);
 if(!hit.length){toast('该报告卡暂无关联的上报数据','error');return}
 const target=hit[0];
 if(typeof openSourceDataDetail==='function'){openSourceDataDetail(target.id);toast('已打开上报数据 '+target.id)}
 else{toast('上报数据模块未加载','error')}
}

/* ---------- 人口信息匹配度（供人工判断"是否同一个人"） ----------
   以组内主卡为基准逐字段比对。相同的字段计数，不同的字段列出差异值。
   仅作参考展示，不参与自动判定：是否同一人由人工判定（重卡/多原发/独立卡）。 */
const POP_FIELDS=[
 {key:'pname', label:'姓名'},
 {key:'psex', label:'性别'},
 {key:'pbirth', label:'出生日期'},
 {key:'pindno', label:'身份证号'},
 {key:'pphone', label:'联系电话'},
 {key:'paddress', label:'户籍地址'}
];
/* 返回 {same:[字段], diff:[{label,base,cur}], level, text, color, bg} */
function popMatch(base,cur){
 const same=[],diff=[];
 POP_FIELDS.forEach(f=>{
  const a=(base&&base[f.key])||'-', b=(cur&&cur[f.key])||'-';
  if(a===b){same.push(f.label)}else{diff.push({label:f.label,base:a,cur:b})}
 });
 /* 身份证号一致=确定同一人；姓名+性别+出生日期一致=高度疑似；否则提示复核 */
 const idSame=same.indexOf('身份证号')>=0;
 const core=['姓名','性别','出生日期'].every(l=>same.indexOf(l)>=0);
 let level,text,color,bg;
 if(idSame&&diff.length===0){level='high';text='完全一致';color='#16a34a';bg='#dcfce7'}
 else if(idSame){level='high';text='身份证一致';color='#16a34a';bg='#dcfce7'}
 else if(core&&diff.length===1){level='mid';text='关键项一致';color='#d97706';bg='#fef3c7'}
 else if(core){level='mid';text='关键项一致';color='#d97706';bg='#fef3c7'}
 else{level='low';text='多项不一致';color='#dc2626';bg='#fee2e2'}
 return {same:same,diff:diff,level:level,text:text,color:color,bg:bg};
}
