function renderMenuPermList(){const rows=menuPermData.map((r,i)=>'<tr><td>'+(i+1)+'</td><td>'+r.code+'</td><td>'+r.name+'</td><td>'+(r.status==='启用'?'<span class="badge badge-success">启用</span>':'<span class="badge badge-muted">禁用</span>')+'</td><td>'+r.sort+'</td><td>'+(r.desc||'-')+'</td><td class="ops"><button class="btn btn-primary btn-xs" onclick="menuPermEdit(\'+i+\')")>编辑</button> <button class="btn btn-danger btn-xs" onclick="menuPermDelete(\'+i+\')")>删除</button></td></tr>').join('');return '<div class="page-toolbar"><div class="page-toolbar-title"><span class="icon">●</span>菜单栏管理</div><div class="toolbar-actions"><button class="btn btn-primary btn-sm" onclick="menuPermAdd()">+ 添加</button></div></div><div class="panel"><div class="panel-body"><div class="table-wrap"><table class="data-table" style="min-width:784px"><thead><tr><th class="num">序号</th><th class="txt">编码</th><th class="txt">名称</th><th class="code">状态</th><th class="num">顺序</th><th class="txt">描述</th><th class="ops">操作</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></div>'}
function renderMenuPermForm(){const isEdit=menuPermState.editingId!==null;const r=isEdit?menuPermData[menuPermState.editingId]:{code:'',name:'',sort:0,status:'启用',desc:''};return '<div class="page-toolbar"><div class="page-toolbar-title"><span class="icon">●</span>'+(isEdit?'编辑菜单':'新增菜单')+'</div><div class="toolbar-actions"><button class="btn btn-primary btn-sm" onclick="menuPermSave()">保存</button> <button class="btn btn-ghost btn-sm" onclick="menuPermState.mode=\'list\';renderPage(\'system-menu\')")>取消</button></div></div><div class="panel"><div class="panel-body"><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;max-width:600px"><div class="form-group"><label>编码 *</label><input type="text" value="'+r.code+'"></div><div class="form-group"><label>名称 *</label><input type="text" value="'+r.name+'"></div><div class="form-group"><label>排列顺序 *</label><input type="number" value="'+r.sort+'"></div><div class="form-group"><label>使用状态</label><select><option value="启用"'+(r.status==='启用'?' selected':'')+'>启用</option><option value="禁用"'+(r.status==='禁用'?' selected':'')+'>禁用</option></select></div></div><div class="form-group" style="max-width:600px;margin-top:12px"><label>描述说明</label><textarea rows="3" style="width:100%">'+(r.desc||'')+'</textarea></div></div></div>'}
function menuPermAdd(){menuPermState.mode='form';menuPermState.editingId=null;renderPage('system-menu')}
function menuPermEdit(idx){menuPermState.mode='form';menuPermState.editingId=idx;renderPage('system-menu')}
function menuPermDelete(idx){showConfirm('确认删除','确定要删除「'+menuPermData[idx].name+'」吗？',()=>{menuPermData.splice(idx,1);toast('删除成功');renderPage('system-menu')})}
function menuPermSave(){menuPermState.mode='list';toast('保存成功');renderPage('system-menu')}

