function renderDictCommon(){const items=dictCommonData[dictCommonState.currentType]||[];const filtered=dictCommonState.keyword?items.filter(r=>r.code.includes(dictCommonState.keyword)||r.name.includes(dictCommonState.keyword)):items;const typeOptions=dictCommonTypes.map(t=>'<option value="'+t.type+'"'+(t.type===dictCommonState.currentType?' selected':'')+'>'+t.name+'</option>').join('');const rows=filtered.map((r,i)=>'<tr><td class="num">'+(i+1)+'</td><td class="txt">'+r.code+'</td><td class="txt">'+r.name+'</td><td class="num">'+r.sort+'</td><td class="code">'+(r.status==='启用'?'<span class="badge badge-success">启用</span>':'<span class="badge badge-muted">禁用</span>')+'</td><td class="code">'+(r.mergeStatus==='已撤并'?'<span class="badge badge-danger">已撤并</span>':'<span class="badge badge-success">未撤并</span>')+'</td><td class="txt">'+(r.mergeCode||'-')+'</td><td class="txt">'+(r.remark||'-')+'</td><td class="ops"><button class="btn btn-primary btn-xs" onclick="dictCommonEdit(\'+i+\')")>编辑</button> <button class="btn btn-danger btn-xs" onclick="dictCommonDelete(\'+i+\')")>删除</button></td></tr>').join('');return '<div class="page-toolbar"><div class="page-toolbar-title"><span class="icon">●</span>常规字典管理</div></div><div class="panel"><div class="panel-body"><div class="filter-toolbar"><div class="form-group"><label>字典类型</label><select onchange="dictCommonState.currentType=this.value;dictCommonState.keyword=\'\';renderPage(\'dict-common\'")>'+typeOptions+'</select></div><div class="form-group search-group"><label>检索内容</label><input type="text" value="'+dictCommonState.keyword+'" placeholder="代码 / 名称" onchange="dictCommonState.keyword=this.value;renderPage(\'dict-common\'")></div><div class="filter-actions"><button class="btn btn-primary btn-sm" onclick="renderPage(\'dict-common\')")>查询</button><button class="btn btn-ghost btn-sm" onclick="dictCommonState.keyword=\'\';renderPage(\'dict-common\')")>重置</button><button class="btn btn-primary btn-sm" onclick="dictCommonAdd()">+ 添加</button></div></div><div class="table-wrap"><table class="data-table" style="min-width:1008px"><thead><tr><th class="num">序号</th><th class="txt">代码</th><th class="txt">名称</th><th class="num">排序</th><th class="code">状态</th><th class="code">撤并状态</th><th class="txt">撤并编码</th><th class="txt">备注</th><th class="ops">操作</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></div>'}
function dictCommonAdd(){dictCommonFormShow('add',null)}
function dictCommonEdit(i){dictCommonFormShow('edit',i)}
function dictCommonDelete(i){const items=dictCommonData[dictCommonState.currentType]||[];if(items[i].mergeStatus!=='已撤并'){toast('请先完成撤并操作后再删除');return}showConfirm('确认删除','确定要删除「'+items[i].name+'」吗？',()=>{items.splice(i,1);toast('删除成功');renderPage('dict-common')})}
function dictCommonFormShow(mode,idx){const items=dictCommonData[dictCommonState.currentType]||[];const r=mode==='edit'?items[idx]:{code:'',name:'',sort:0,status:'启用',mergeStatus:'未撤并',mergeCode:'',remark:''};toast(mode==='edit'?'编辑字典项':'新增字典项')}
function dictCommonFormSave(idx){const code=document.getElementById('dcCode').value.trim();const name=document.getElementById('dcName').value.trim();if(!code||!name){toast('代码和名称为必填项');return}const items=dictCommonData[dictCommonState.currentType]||[];const data={code:code,name:name,sort:parseInt(document.getElementById('dcSort').value)||0,status:document.getElementById('dcStatus').value,mergeStatus:document.getElementById('dcMergeStatus').value,mergeCode:document.getElementById('dcMergeCode').value,remark:document.getElementById('dcRemark').value};if(idx!==null&&idx!=='null'&&items[idx]){Object.assign(items[idx],data)}else{items.push(data)}document.querySelectorAll('.news-confirm-modal').forEach(m=>m.remove());toast('保存成功');renderPage('dict-common')}

