function renderDictCondition(){const rows=dictConditionData.map((r,i)=>'<tr><td class="num">'+(i+1)+'</td><td class="txt">'+r.name+'</td><td class="txt" style="max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+r.expression+'">'+r.expression+'</td><td class="txt">'+r.desc+'</td><td class="code">'+(r.status==='正确'?'<span class="badge badge-success">正确</span>':'<span class="badge badge-danger">错误</span>')+'</td><td class="code">'+r.createTime+'</td><td class="ops"><button class="btn btn-primary btn-xs" onclick="dictConditionEdit(\'+i+\')")>编辑</button> <button class="btn btn-danger btn-xs" onclick="dictConditionDelete(\'+i+\')")>删除</button></td></tr>').join('');return '<div class="page-toolbar"><div class="page-toolbar-title"><span class="icon">●</span>自定义条件管理</div></div><div class="panel"><div class="panel-body"><div class="filter-toolbar"><div class="form-group search-group"><label>检索内容</label><input type="text" placeholder="条件名称"></div><div class="form-group"><label>创建日期</label><input type="date"></div><div class="filter-actions"><button class="btn btn-primary btn-sm" onclick="toast(\'查询完成\')")>查询</button><button class="btn btn-ghost btn-sm" onclick="toast(\'已重置\')")>重置</button><button class="btn btn-primary btn-sm" onclick="dictConditionAdd()">+ 添加</button></div></div><div class="table-wrap"><table class="data-table" style="min-width:784px"><thead><tr><th class="num">序号</th><th class="txt">条件名称</th><th class="txt">表达式</th><th class="txt">说明</th><th class="code">校验状态</th><th class="code">创建日期</th><th class="ops">操作</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></div>'}
